   339	// readTranscriptFromFullRefs reads the raw transcript for a checkpoint session
   340	// by searching /full/current first, then archived generations in reverse order.
   341	// If not found locally, it discovers and fetches remote /full/* refs.
   342	func (s *V2GitStore) readTranscriptFromFullRefs(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int, agentType types.AgentType) ([]byte, error) {
   343		if err := ctx.Err(); err != nil {
   344			return nil, err //nolint:wrapcheck // Propagating context cancellation
   345		}
   346	
   347		sessionPath := fmt.Sprintf("%s/%d", checkpointID.Path(), sessionIndex)
   348	
   349		// Search locally first.
   350		transcript, err := s.readTranscriptFromRef(plumbing.ReferenceName(paths.V2FullCurrentRefName), sessionPath, agentType)
   351		if err == nil && len(transcript) > 0 {
   352			return transcript, nil
   353		}
   354	
   355		archived, err := s.listArchivedFullRefs()
   356		if err != nil {
   357			return nil, err
   358		}
   359		for i := len(archived) - 1; i >= 0; i-- {
   360			transcript, err := s.readTranscriptFromRef(archived[i], sessionPath, agentType)
   361			if err == nil && len(transcript) > 0 {
   362				return transcript, nil
   363			}
   364		}
   365	
   366		if fetchErr := s.fetchRemoteFullRefs(ctx); fetchErr != nil {
   367			logging.Debug(ctx, "failed to fetch remote /full/* refs",
   368				slog.String("error", fetchErr.Error()),
   369			)
   370			return nil, nil
   371		}
   372	
   373		// Search again after fetching. Current is force-fetched so a stale or empty
   374		// local /full/current can recover, while archived refs are fetched only when
   375		// absent locally.
   376		transcript, err = s.readTranscriptFromRef(plumbing.ReferenceName(paths.V2FullCurrentRefName), sessionPath, agentType)
   377		if err == nil && len(transcript) > 0 {
   378			return transcript, nil
   379		}
   380	
   381		// Skip refs already scanned pre-fetch. Use a membership set rather than a
   382		// length boundary: archive ref names can interleave in lex order across
   383		// machines (clocks diverge per the fetchRemoteFullRefs comment), so a new
   384		// ref may sort before existing local ones.
   385		checkedArchived := make(map[plumbing.ReferenceName]struct{}, len(archived))
   386		for _, ref := range archived {
   387			checkedArchived[ref] = struct{}{}
   388		}
   389		archived, err = s.listArchivedFullRefs()
   390		if err != nil {
   391			return nil, nil //nolint:nilerr // Best-effort: fetch-on-demand failure shouldn't block resume.
   392		}
   393		for i := len(archived) - 1; i >= 0; i-- {
   394			ref := archived[i]
   395			if _, checked := checkedArchived[ref]; checked {
   396				continue
   397			}
   398			transcript, err := s.readTranscriptFromRef(ref, sessionPath, agentType)
   399			if err == nil && len(transcript) > 0 {
   400				return transcript, nil
   401			}
   402		}
   403	
   404		return nil, nil
   405	}
