   407	func (s *V2GitStore) listArchivedFullRefs() ([]plumbing.ReferenceName, error) {
   408		refs, err := s.repo.References()
   409		if err != nil {
   410			return nil, fmt.Errorf("failed to list references: %w", err)
   411		}
   412	
   413		prefix := v2FullRefPrefix()
   414		var archived []string
   415		err = refs.ForEach(func(ref *plumbing.Reference) error {
   416			name := ref.Name().String()
   417			if !strings.HasPrefix(name, prefix) {
   418				return nil
   419			}
   420			suffix := strings.TrimPrefix(name, prefix)
   421			if !isV2ArchivedFullRefSuffix(suffix) {
   422				return nil
   423			}
   424			archived = append(archived, name)
   425			return nil
   426		})
   427		if err != nil {
   428			return nil, fmt.Errorf("failed to iterate references: %w", err)
   429		}
   430	
   431		sort.Strings(archived)
   432		result := make([]plumbing.ReferenceName, 0, len(archived))
   433		for _, ref := range archived {
   434			result = append(result, plumbing.ReferenceName(ref))
   435		}
   436		return result, nil
   437	}
