   439	// fetchRemoteFullRefs discovers and fetches v2 /full/* refs from the effective
   440	// checkpoint fetch target. /full/current is force-fetched; archived generation
   441	// refs are fetched only when absent locally because old archives should be
   442	// immutable but may have diverged across machines.
   443	func (s *V2GitStore) fetchRemoteFullRefs(ctx context.Context) error {
   444		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
   445		defer cancel()
   446	
   447		repoRoot, _, err := s.gs.repoDirs(ctx)
   448		if err != nil {
   449			return err
   450		}
   451	
   452		fetchTarget := v2FullRefsFetchTarget(ctx, repoRoot)
   453		output, err := remote.LsRemoteInDir(ctx, repoRoot, fetchTarget, v2FullRefPrefix()+"*")
   454		if err != nil {
   455			return fmt.Errorf("ls-remote failed: %w", err)
   456		}
   457	
   458		var refSpecs []string
   459		for line := range strings.SplitSeq(strings.TrimSpace(string(output)), "\n") {
   460			if line == "" {
   461				continue
   462			}
   463			parts := strings.Fields(line)
   464			if len(parts) < 2 {
   465				continue
   466			}
   467			remoteRefName := parts[1]
   468			if !isV2FetchableFullRef(remoteRefName) {
   469				continue
   470			}
   471	
   472			if remoteRefName != paths.V2FullCurrentRefName {
   473				if _, refErr := s.repo.Reference(plumbing.ReferenceName(remoteRefName), true); refErr == nil {
   474					continue
   475				}
   476			}
   477	
   478			refSpecs = append(refSpecs, fmt.Sprintf("+%s:%s", remoteRefName, remoteRefName))
   479		}
   480	
   481		if len(refSpecs) == 0 {
   482			return nil
   483		}
   484	
   485		if fetchOutput, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
   486			Remote:   fetchTarget,
   487			RefSpecs: refSpecs,
   488			NoTags:   true,
   489			NoFilter: true,
   490			Dir:      repoRoot,
   491		}); fetchErr != nil {
   492			if output := strings.TrimSpace(string(fetchOutput)); output != "" {
   493				return fmt.Errorf("fetch failed: %s: %w", output, fetchErr)
   494			}
   495			return fmt.Errorf("fetch failed: %w", fetchErr)
   496		}
   497	
   498		return nil
   499	}
