   509	func v2FullRefPrefix() string {
   510		return strings.TrimSuffix(paths.V2FullCurrentRefName, "current")
   511	}
   512	
   513	func isV2FetchableFullRef(refName string) bool {
   514		if refName == paths.V2FullCurrentRefName {
   515			return true
   516		}
   517		if !strings.HasPrefix(refName, v2FullRefPrefix()) {
   518			return false
