   544		}
   545	
   546		rootTree, err := s.repo.TreeObject(rootTreeHash)
   547		if err != nil {
   548			return nil, fmt.Errorf("failed to read tree: %w", err)
   549		}
   550	
   551		sessionTree, err := rootTree.Tree(sessionPath)
   552		if err != nil {
   553			return nil, fmt.Errorf("session path %s not found: %w", sessionPath, err)
