   559	// readTranscriptFromObjectTree reads and reassembles a transcript from a git tree object.
   560	// Handles both chunked and non-chunked transcripts. Uses agent-aware reassembly
   561	// when agentType is known, falling back to JSONL reassembly otherwise.
   562	func readTranscriptFromObjectTree(tree *object.Tree, agentType types.AgentType) ([]byte, error) {
   563		var chunkFiles []string
   564		var hasBaseFile bool
   565	
   566		for _, entry := range tree.Entries {
   567			if entry.Name == paths.V2RawTranscriptFileName {
   568				hasBaseFile = true
   569			}
   570			if strings.HasPrefix(entry.Name, paths.V2RawTranscriptFileName+".") {
   571				idx := agent.ParseChunkIndex(entry.Name, paths.V2RawTranscriptFileName)
   572				if idx > 0 {
   573					chunkFiles = append(chunkFiles, entry.Name)
   574				}
   575			}
   576		}
   577	
   578		// If chunk files exist, reassemble all chunks (base file is chunk 0)
   579		if len(chunkFiles) > 0 {
   580			chunkFiles = agent.SortChunkFiles(chunkFiles, paths.V2RawTranscriptFileName)
   581			if hasBaseFile {
   582				chunkFiles = append([]string{paths.V2RawTranscriptFileName}, chunkFiles...)
   583			}
   584	
   585			var chunks [][]byte
   586			for _, chunkFile := range chunkFiles {
   587				file, fileErr := tree.File(chunkFile)
   588				if fileErr != nil {
   589					continue
   590				}
   591				content, contentErr := file.Contents()
   592				if contentErr != nil {
   593					continue
   594				}
   595				chunks = append(chunks, []byte(content))
   596			}
   597	
   598			if len(chunks) > 0 {
   599				result, reassembleErr := agent.ReassembleTranscript(chunks, agentType)
   600				if reassembleErr != nil {
   601					return nil, fmt.Errorf("failed to reassemble transcript: %w", reassembleErr)
   602				}
   603				return result, nil
   604			}
   605		}
   606	
   607		// No chunk files — read base file directly (non-chunked transcript)
   608		if hasBaseFile {
   609			file, err := tree.File(paths.V2RawTranscriptFileName)
   610			if err == nil {
   611				content, contentErr := file.Contents()
   612				if contentErr == nil {
   613					return []byte(content), nil
   614				}
   615			}
   616		}
   617	
   618		return nil, nil
   619	}
