   714	// writeTranscript writes the transcript and content hash to the checkpoint entries.
   715	// Returns (true, nil) if files were written, (false, nil) if transcript was empty.
   716	func (s *GitStore) writeTranscript(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (bool, error) {
   717		logCtx := logging.WithComponent(ctx, "checkpoint")
   718		transcriptBytes := opts.Transcript.Bytes()
   719	
   720		// TranscriptPath fallback: data read from disk is an untrusted source,
   721		// so we redact it here. The in-memory path (opts.Transcript) is already
   722		// pre-redacted by the caller — enforced by the RedactedBytes type.
   723		if len(transcriptBytes) == 0 && opts.TranscriptPath != "" {
   724			rawData, readErr := os.ReadFile(opts.TranscriptPath)
   725			if readErr != nil {
   726				// Non-fatal: transcript may not exist yet
   727				rawData = nil
   728			}
   729			if len(rawData) > 0 {
   730				redacted, redactErr := redact.JSONLBytes(rawData)
   731				if redactErr != nil {
   732					return false, fmt.Errorf("failed to redact transcript from file: %w", redactErr)
   733				}
   734				transcriptBytes = redacted.Bytes()
   735			}
   736		}
   737		if len(transcriptBytes) == 0 {
   738			return false, nil
   739		}
   740	
   741		if opts.Agent == agent.AgentTypeCodex {
   742			transcriptBytes = codex.SanitizePortableTranscript(transcriptBytes)
   743		}
   744	
   745		// Chunk the transcript if it's too large
   746		chunkStart := time.Now()
   747		chunkCtx, chunkTranscriptSpan := perf.Start(ctx, "chunk_transcript")
   748		chunks, err := agent.ChunkTranscript(chunkCtx, transcriptBytes, opts.Agent)
   749		if err != nil {
   750			chunkTranscriptSpan.RecordError(err)
   751			chunkTranscriptSpan.End()
   752			return false, fmt.Errorf("failed to chunk transcript: %w", err)
   753		}
   754		chunkTranscriptSpan.End()
   755		chunkDuration := time.Since(chunkStart)
   756	
   757		// Write chunk files
   758		blobStart := time.Now()
   759		blobCtx, writeTranscriptBlobsSpan := perf.Start(chunkCtx, "write_transcript_blobs")
   760		for i, chunk := range chunks {
   761			chunkPath := basePath + agent.ChunkFileName(paths.TranscriptFileName, i)
   762			blobHash, err := CreateBlobFromContent(s.repo, chunk)
   763			if err != nil {
   764				writeTranscriptBlobsSpan.RecordError(err)
   765				writeTranscriptBlobsSpan.End()
   766				return false, err
   767			}
   768			entries[chunkPath] = object.TreeEntry{
   769				Name: chunkPath,
   770				Mode: filemode.Regular,
   771				Hash: blobHash,
   772			}
   773		}
   774		writeTranscriptBlobsSpan.End()
   775		blobDuration := time.Since(blobStart)
   776	
   777		// Content hash for deduplication (hash of full transcript)
   778		contentHashStart := time.Now()
   779		_, contentHashSpan := perf.Start(blobCtx, "write_transcript_content_hash")
   780		contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcriptBytes))
   781		hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
   782		if err != nil {
   783			contentHashSpan.RecordError(err)
   784			contentHashSpan.End()
   785			return false, err
   786		}
   787		entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
   788			Name: basePath + paths.ContentHashFileName,
   789			Mode: filemode.Regular,
   790			Hash: hashBlob,
   791		}
   792		contentHashSpan.End()
   793	
   794		logging.Debug(logCtx, "write transcript timings",
   795			slog.String("session_id", opts.SessionID),
   796			slog.String("checkpoint_id", opts.CheckpointID.String()),
   797			slog.String("agent", string(opts.Agent)),
   798			slog.Int64("chunk_transcript_ms", chunkDuration.Milliseconds()),
   799			slog.Int64("write_transcript_blobs_ms", blobDuration.Milliseconds()),
   800			slog.Int64("write_transcript_content_hash_ms", time.Since(contentHashStart).Milliseconds()),
   801			slog.Int("transcript_bytes", len(transcriptBytes)),
   802			slog.Int("chunk_count", len(chunks)),
   803		)
   804		return true, nil
   805	}
