   807	// mergeFilesTouched combines two file lists, removing duplicates.
   808	// All paths are normalized to forward slashes for platform-agnostic storage.
   809	func mergeFilesTouched(existing, additional []string) []string {
   810		seen := make(map[string]bool)
   811		var result []string
   812	
   813		for _, f := range existing {
   814			f = filepath.ToSlash(f)
   815			if !seen[f] {
   816				seen[f] = true
   817				result = append(result, f)
   818			}
   819		}
   820		for _, f := range additional {
   821			f = filepath.ToSlash(f)
   822			if !seen[f] {
   823				seen[f] = true
   824				result = append(result, f)
   825			}
   826		}
   827	
   828		sort.Strings(result)
   829		return result
   830	}
