    97	// and handled by the push path's tree merge.
    98	//
    99	// Repair strategy: cherry-pick local commits onto remote tip, preserving all data.
   100	// Checkpoint shards use unique paths (<id[:2]>/<id[2:]>/), so cherry-picks always
   101	// apply cleanly.
   102	//
   103	// Progress messages are written to w (typically os.Stderr for hooks or
   104	// cmd.ErrOrStderr() for commands).
   105	// The remote ref can be either a remote-tracking ref or a temporary fetched ref.
   106	func ReconcileDisconnectedMetadataBranch(
   107		ctx context.Context,
   108		repo *git.Repository,
   109		remoteRefName plumbing.ReferenceName,
   110		w io.Writer,
   111	) error {
   112		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   113	
   114		// Check local branch
   115		localRef, err := repo.Reference(refName, true)
   116		if errors.Is(err, plumbing.ErrReferenceNotFound) {
   117			return nil // No local branch — nothing to reconcile
   118		}
   119		if err != nil {
   120			return fmt.Errorf("failed to check local metadata branch: %w", err)
   121		}
   122	
   123		// Check remote-tracking branch
   124		remoteRef, err := repo.Reference(remoteRefName, true)
   125		if errors.Is(err, plumbing.ErrReferenceNotFound) {
   126			return nil // No remote branch — nothing to reconcile
   127		}
   128		if err != nil {
   129			return fmt.Errorf("failed to check remote metadata branch: %w", err)
   130		}
   131	
   132		localHash := localRef.Hash()
   133		remoteHash := remoteRef.Hash()
   134	
   135		// Same hash — nothing to do
   136		if localHash == remoteHash {
   137			return nil
   138		}
   139	
   140		// Check if disconnected using git merge-base
   141		repoPath, err := getRepoPath(repo)
   142		if err != nil {
   143			return err
   144		}
   145	
   146		disconnected, err := isDisconnected(ctx, repoPath, localHash.String(), remoteHash.String())
   147		if err != nil {
   148			return fmt.Errorf("failed to check metadata branch ancestry: %w", err)
   149		}
   150		if !disconnected {
   151			// Shared ancestry (diverged or ancestor) — not our problem
   152			return nil
   153		}
   154	
   155		// Disconnected — cherry-pick local commits onto remote tip
   156		fmt.Fprintln(w, "[entire] Detected disconnected session metadata (local and remote share no common ancestor)")
   157	
   158		shallow, err := loadShallowHashes(ctx, repoPath)
   159		if err != nil {
   160			return fmt.Errorf("failed to load shallow boundaries: %w", err)
   161		}
   162	
   163		// Collect local commits oldest-first
   164		localCommits, err := collectCommitChain(repo, localHash, shallow)
   165		if err != nil {
