   374	// lsRemoteRef runs git ls-remote and returns the hash for a specific ref.
   375	// Returns plumbing.ZeroHash if the ref doesn't exist on the remote.
   376	func lsRemoteRef(ctx context.Context, repoPath, remoteName, refName string) (plumbing.Hash, error) {
   377		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
   378		defer cancel()
   379	
   380		fetchTarget, err := remote.ResolveFetchTarget(ctx, remoteName)
   381		if err != nil {
   382			return plumbing.ZeroHash, fmt.Errorf("resolve fetch target for ls-remote: %w", err)
   383		}
   384	
   385		output, err := remote.LsRemoteInDir(ctx, repoPath, fetchTarget, refName)
   386		if err != nil {
   387			return plumbing.ZeroHash, fmt.Errorf("git ls-remote %s failed: %w", remote.RedactURL(fetchTarget), err)
   388		}
   389	
   390		line := strings.TrimSpace(string(output))
   391		if line == "" {
   392			return plumbing.ZeroHash, nil
   393		}
   394	
   395		parts := strings.Fields(line)
   396		if len(parts) < 2 {
   397			return plumbing.ZeroHash, nil
   398		}
   399	
   400		return plumbing.NewHash(parts[0]), nil
   401	}
