   403	// fetchRefToTemp fetches a remote ref to a temporary local ref for comparison.
   404	func fetchRefToTemp(ctx context.Context, repoPath, remoteName, srcRef, dstRef string) error {
   405		ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
   406		defer cancel()
   407	
   408		fetchTarget, err := remote.ResolveFetchTarget(ctx, remoteName)
   409		if err != nil {
   410			return fmt.Errorf("resolve fetch target for doctor v2 fetch: %w", err)
   411		}
   412	
   413		refspec := fmt.Sprintf("+%s:%s", srcRef, dstRef)
   414		output, err := remote.Fetch(ctx, remote.FetchOptions{
   415			Remote:    fetchTarget,
   416			RefSpecs:  []string{refspec},
   417			NoTags:    true,
   418			Unshallow: true,
   419			Dir:       repoPath,
   420		})
   421		if err != nil {
   422			redactedURL := remote.RedactURL(fetchTarget)
   423			msg := strings.TrimSpace(strings.ReplaceAll(string(output), fetchTarget, redactedURL))
   424			if msg != "" {
   425				return fmt.Errorf("git fetch %s failed: %s: %w", redactedURL, msg, err)
   426			}
   427			return fmt.Errorf("git fetch %s failed: %w", redactedURL, err)
   428		}
   429		return nil
   430	}
